-- The curated starter catalog (the same 66 gifts as lib/catalog-data.ts).
-- price_cents is the source price: what the supplier charges you to drop-ship it.
-- Shoppers pay that plus your markup (MARKUP_PERCENT, 10 by default).
-- Add, edit or hide products in /admin. ships_by 'supplier' means they drop-ship.
-- Turns off the old starter list from the first version, if it was loaded.
update products set active = false where sku in ('coffee-kit','tea-sampler','chocolate-box','skillet','cutting-board','flutes','hammock','headlamp','cooler','foam-roller','spa-set','dopp-kit','silk-set','blanket','speaker','earbuds','smart-tracker','keyboard','board-game','book-box','instant-camera','watercolor','embroidery','herb-garden','pet-portrait','wallet','necklace','watch','pickleball','robot-kit','brick-set','slime-lab','art-easel','scooter','baby-book','baby-blanket','grad-kit','grad-frame','get-well','thank-you');

on conflict (sku) do update set name = excluded.name, description = excluded.description, emoji = excluded.emoji,
  price_cents = excluded.price_cents, tags = excluded.tags, styles = excluded.styles, occasions = excluded.occasions,
  sex = excluded.sex, age_min = excluded.age_min, age_max = excluded.age_max, ships_by = excluded.ships_by, active = true;
